    const pr = JSON.parse(prJson) as { headRefName?: unknown; isCrossRepository?: unknown };
    return {
      branch: typeof pr.headRefName === "string" ? pr.headRefName.trim() : "",
      crossRepository: pr.isCrossRepository === true,
